"""Validation script for pipeline outputs.

Checks existence, non-emptiness, and structural integrity of key
upstream pipeline CSV files.  Writes a JSON summary to
outputs/t14_validation_summary.json.
"""

import csv
import json
import os
import sys


# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
OUTPUT_DIR = "outputs"
SUMMARY_PATH = os.path.join(OUTPUT_DIR, "t14_validation_summary.json")

EXPECTED_FILES = {
    "t01_selected_indicators.csv": {
        "required_columns": [
            "indicator_id",
            "indicator_name",
            "theme",
            "justification",
            "expected_direction",
        ],
        "min_rows": 1,
    },
    "t05_clean_stops.csv": {
        "required_columns": ["stop_id", "stop_name", "stop_lat", "stop_lon"],
        "min_rows": 1,
    },
    "t08_pois_clean.csv": {
        "required_columns": ["qid", "label", "poi_type", "latitude", "longitude", "source"],
        "min_rows": 1,
    },
    "t10_accessibility_scores.csv": {
        "required_columns": [
            "qid",
            "label",
            "poi_type",
            "distance_m",
            "n_departures",
            "n_routes",
            "accessibility_score",
        ],
        "min_rows": 1,
    },
    "t13_city_clusters.csv": {
        "required_columns": ["city_id", "city_name", "year", "cluster_id"],
        "min_rows": 1,
    },
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def check_file_exists(name: str) -> dict:
    """Return a check dict reporting whether the file exists and is non-empty."""
    path = os.path.join(OUTPUT_DIR, name)
    if not os.path.isfile(path):
        return {
            "check_name": f"file_exists_{name}",
            "passed": False,
            "message": f"{path} does not exist.",
        }
    if os.path.getsize(path) == 0:
        return {
            "check_name": f"file_exists_{name}",
            "passed": False,
            "message": f"{path} exists but is empty.",
        }
    return {
        "check_name": f"file_exists_{name}",
        "passed": True,
        "message": f"{path} exists and is non-empty.",
    }


def check_columns(name: str, required_columns: list) -> dict:
    """Return a check dict reporting whether the CSV has the expected columns."""
    path = os.path.join(OUTPUT_DIR, name)
    if not os.path.isfile(path):
        return {
            "check_name": f"columns_{name}",
            "passed": False,
            "message": f"Cannot check columns: {path} does not exist.",
        }
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            header = next(reader, None)
        if header is None:
            return {
                "check_name": f"columns_{name}",
                "passed": False,
                "message": f"{path} has no header row.",
            }
        missing = [c for c in required_columns if c not in header]
        if missing:
            return {
                "check_name": f"columns_{name}",
                "passed": False,
                "message": f"{path} is missing required columns: {', '.join(missing)}.",
            }
        return {
            "check_name": f"columns_{name}",
            "passed": True,
            "message": f"{path} contains all required columns.",
        }
    except Exception as exc:
        return {
            "check_name": f"columns_{name}",
            "passed": False,
            "message": f"Error reading {path}: {exc}",
        }


def check_row_count(name: str, min_rows: int) -> dict:
    """Return a check dict reporting whether the CSV has enough data rows."""
    path = os.path.join(OUTPUT_DIR, name)
    if not os.path.isfile(path):
        return {
            "check_name": f"row_count_{name}",
            "passed": False,
            "message": f"Cannot check rows: {path} does not exist.",
        }
    try:
        with open(path, newline="", encoding="utf-8") as fh:
            reader = csv.reader(fh)
            header = next(reader, None)
            if header is None:
                return {
                    "check_name": f"row_count_{name}",
                    "passed": False,
                    "message": f"{path} has no header row.",
                }
            count = sum(1 for _ in reader)
        if count < min_rows:
            return {
                "check_name": f"row_count_{name}",
                "passed": False,
                "message": f"{path} has {count} data rows (expected >= {min_rows}).",
            }
        return {
            "check_name": f"row_count_{name}",
            "passed": True,
            "message": f"{path} has {count} data rows (>= {min_rows}).",
        }
    except Exception as exc:
        return {
            "check_name": f"row_count_{name}",
            "passed": False,
            "message": f"Error reading {path}: {exc}",
        }


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    results: list[dict] = []

    for name, spec in EXPECTED_FILES.items():
        # 1. Existence / non-empty
        results.append(check_file_exists(name))

        # 2. Required columns
        results.append(check_columns(name, spec["required_columns"]))

        # 3. Row count
        results.append(check_row_count(name, spec["min_rows"]))

    # Write summary
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    with open(SUMMARY_PATH, "w", encoding="utf-8") as fh:
        json.dump(results, fh, indent=2, ensure_ascii=False)

    # Print summary to stdout
    passed = sum(1 for r in results if r["passed"])
    total = len(results)
    print(f"Validation complete: {passed}/{total} checks passed.")
    for r in results:
        status = "PASS" if r["passed"] else "FAIL"
        print(f"  [{status}] {r['check_name']}: {r['message']}")

    if passed < total:
        sys.exit(1)


if __name__ == "__main__":
    main()
